from collections import deque
from typing import List

class Solution:
    def minOperations(self, nums: List[int], target: List[int]) -> int:
        # BFS on array configurations or check element counts
        # If arrays already equal, 0 operations
        if nums == target:
            return 0
        if sum(nums) != sum(target):
            return -1

        start = tuple(nums)
        goal = tuple(target)
        queue = deque([(start, 0)])
        visited = {start}

        while queue:
            curr, steps = queue.popleft()
            if curr == goal:
                return steps
            if steps >= 6: # Depth limit for small graph search
                continue

            # Try merge two adjacent elements
            for i in range(len(curr) - 1):
                merged = curr[:i] + (curr[i] + curr[i + 1],) + curr[i + 2:]
                if merged not in visited:
                    visited.add(merged)
                    queue.append((merged, steps + 1))

            # Try split an element > 1 into two parts
            for i in range(len(curr)):
                if curr[i] > 1:
                    for part in range(1, curr[i]):
                        split_arr = curr[:i] + (part, curr[i] - part) + curr[i + 1:]
                        if split_arr not in visited and len(split_arr) <= len(target) + 2:
                            visited.add(split_arr)
                            queue.append((split_arr, steps + 1))

        return -1
