#include <vector>
#include <queue>
#include <set>
#include <numeric>

class Solution {
public:
    int minOperations(std::vector<int>& nums, std::vector<int>& target) {
        if (nums == target) return 0;
        long long s1 = std::accumulate(nums.begin(), nums.end(), 0LL);
        long long s2 = std::accumulate(target.begin(), target.end(), 0LL);
        if (s1 != s2) return -1;

        std::set<std::vector<int>> visited;
        std::queue<std::pair<std::vector<int>, int>> q;
        q.push({nums, 0});
        visited.insert(nums);

        while (!q.empty()) {
            auto [curr, steps] = q.front();
            q.pop();

            if (curr == target) return steps;
            if (steps >= 6) continue;

            // Merge
            for (size_t i = 0; i + 1 < curr.size(); ++i) {
                std::vector<int> next_arr = curr;
                next_arr[i] += next_arr[i + 1];
                next_arr.erase(next_arr.begin() + i + 1);
                if (!visited.count(next_arr)) {
                    visited.insert(next_arr);
                    q.push({next_arr, steps + 1});
                }
            }

            // Split
            for (size_t i = 0; i < curr.size(); ++i) {
                if (curr[i] > 1) {
                    for (int part = 1; part < curr[i]; ++part) {
                        std::vector<int> next_arr = curr;
                        next_arr[i] = part;
                        next_arr.insert(next_arr.begin() + i + 1, curr[i] - part);
                        if (!visited.count(next_arr) && next_arr.size() <= target.size() + 2) {
                            visited.insert(next_arr);
                            q.push({next_arr, steps + 1});
                        }
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minOperations(int[] nums, int[] target) {
        if (Arrays.equals(nums, target)) return 0;
        long s1 = 0, s2 = 0;
        for (int x : nums) s1 += x;
        for (int x : target) s2 += x;
        if (s1 != s2) return -1;

        List<Integer> start = new ArrayList<>();
        for (int x : nums) start.add(x);
        List<Integer> goal = new ArrayList<>();
        for (int x : target) goal.add(x);

        Set<String> visited = new HashSet<>();
        Queue<Pair> q = new ArrayDeque<>();
        q.offer(new Pair(start, 0));
        visited.add(start.toString());

        while (!q.isEmpty()) {
            Pair cur = q.poll();
            if (cur.arr.equals(goal)) return cur.steps;
            if (cur.steps >= 6) continue;

            // Merge
            for (int i = 0; i + 1 < cur.arr.size(); i++) {
                List<Integer> nextArr = new ArrayList<>(cur.arr);
                int mergedVal = nextArr.get(i) + nextArr.get(i + 1);
                nextArr.set(i, mergedVal);
                nextArr.remove(i + 1);
                if (visited.add(nextArr.toString())) {
                    q.offer(new Pair(nextArr, cur.steps + 1));
                }
            }

            // Split
            for (int i = 0; i < cur.arr.size(); i++) {
                int val = cur.arr.get(i);
                if (val > 1) {
                    for (int part = 1; part < val; part++) {
                        List<Integer> nextArr = new ArrayList<>(cur.arr);
                        nextArr.set(i, part);
                        nextArr.add(i + 1, val - part);
                        if (nextArr.size() <= target.length + 2 && visited.add(nextArr.toString())) {
                            q.offer(new Pair(nextArr, cur.steps + 1));
                        }
                    }
                }
            }
        }
        return -1;
    }

    static class Pair {
        List<Integer> arr;
        int steps;
        Pair(List<Integer> arr, int steps) {
            this.arr = arr;
            this.steps = steps;
        }
    }
}

var minOperations = function(nums, target) {
    if (JSON.stringify(nums) === JSON.stringify(target)) return 0;
    const s1 = nums.reduce((a, b) => a + b, 0);
    const s2 = target.reduce((a, b) => a + b, 0);
    if (s1 !== s2) return -1;

    const goalStr = JSON.stringify(target);
    const visited = new Set();
    const queue = [[nums, 0]];
    visited.add(JSON.stringify(nums));

    while (queue.length > 0) {
        const [curr, steps] = queue.shift();
        if (JSON.stringify(curr) === goalStr) return steps;
        if (steps >= 6) continue;

        // Merge
        for (let i = 0; i + 1 < curr.length; i++) {
            const nextArr = curr.slice();
            nextArr[i] += nextArr[i + 1];
            nextArr.splice(i + 1, 1);
            const key = JSON.stringify(nextArr);
            if (!visited.has(key)) {
                visited.add(key);
                queue.push([nextArr, steps + 1]);
            }
        }

        // Split
        for (let i = 0; i < curr.length; i++) {
            if (curr[i] > 1) {
                for (let part = 1; part < curr[i]; part++) {
                    const nextArr = curr.slice();
                    nextArr[i] = part;
                    nextArr.splice(i + 1, 0, curr[i] - part);
                    const key = JSON.stringify(nextArr);
                    if (!visited.has(key) && nextArr.length <= target.length + 2) {
                        visited.add(key);
                        queue.push([nextArr, steps + 1]);
                    }
                }
            }
        }
    }
    return -1;
};
